'use strict';
const crypto = require('crypto');
const http = require('http');
const url = require('url');

// Webhook signature verification middleware
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET || 'default-dev-secret';
const MAX_BODY_SIZE = 1024 * 1024; // 1MB
const TIMESTAMP_TOLERANCE = 300; // 5 minutes

class WebhookVerifier {
  constructor(secret, options = {}) {
    this.secret = secret;
    this.tolerance = options.tolerance || TIMESTAMP_TOLERANCE;
    this.algorithm = options.algorithm || 'sha256';
    this._requestLog = [];
  }

  /**
   * Compute expected signature for a payload
   * @param {string} timestamp - Unix timestamp
   * @param {string} body - Raw request body
   * @returns {string} hex-encoded HMAC signature
   */
  _computeSignature(timestamp, body) {
    const signedContent = `${timestamp}.${body}`;
    const hmac = crypto.createHmac(this.algorithm, this.secret);
    hmac.update(signedContent, 'utf8');
    return hmac.digest('hex');
  }

  /**
   * Verify timestamp is within tolerance window
   * @param {string} timestamp - Unix timestamp from header
   * @returns {boolean}
   */
  _verifyTimestamp(timestamp) {
    const ts = parseInt(timestamp, 10);
    if (isNaN(ts)) return false;
    const now = Math.floor(Date.now() / 1000);
    return Math.abs(now - ts) <= this.tolerance;
  }

  /**
   * Parse the signature header format: t=<timestamp>,v1=<signature>
   * @param {string} header - Raw signature header value
   * @returns {object|null} Parsed components
   */
  _parseSignatureHeader(header) {
    if (!header || typeof header !== 'string') return null;

    const parts = header.split(',');
    const elements = {};

    for (const part of parts) {
      const [key, value] = part.split('=', 2);
      if (key && value) {
        elements[key.trim()] = value.trim();
      }
    }

    if (!elements.t || !elements.v1) return null;
    return { timestamp: elements.t, signature: elements.v1 };
  }

  /**
   * Constant-time comparison of two signature values
   * Converts both to Buffer for timing-safe comparison
   * @param {string} provided - Signature from request header
   * @param {string} expected - Computed signature
   * @returns {boolean}
   */
  _safeCompare(provided, expected) {
    // Convert hex strings to buffers for comparison
    const providedBuf = Buffer.from(provided, 'hex');
    const expectedBuf = Buffer.from(expected, 'hex');

    if (providedBuf.length !== expectedBuf.length) {
      return false;
    }

    return crypto.timingSafeEqual(providedBuf, expectedBuf);
  }

  /**
   * Full verification of webhook signature
   * @param {string} signatureHeader - X-Webhook-Signature header
   * @param {string} body - Raw request body
   * @returns {{valid: boolean, error?: string}}
   */
  verify(signatureHeader, body) {
    const parsed = this._parseSignatureHeader(signatureHeader);
    if (!parsed) {
      return { valid: false, error: 'Invalid signature header format' };
    }

    if (!this._verifyTimestamp(parsed.timestamp)) {
      return { valid: false, error: 'Timestamp outside tolerance window' };
    }

    const expectedSignature = this._computeSignature(parsed.timestamp, body);
    const isValid = this._safeCompare(parsed.signature, expectedSignature);

    this._requestLog.push({
      timestamp: parsed.timestamp,
      valid: isValid,
      receivedAt: Date.now()
    });

    return { valid: isValid };
  }
}

// Event processing pipeline
class EventProcessor {
  constructor() {
    this.handlers = new Map();
    this._processingQueue = [];
  }

  registerHandler(eventType, handler) {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, []);
    }
    this.handlers.get(eventType).push(handler);
  }

  async processEvent(event) {
    const handlers = this.handlers.get(event.type) || [];
    const results = [];

    for (const handler of handlers) {
      try {
        const result = await handler(event.data);
        results.push({ success: true, result });
      } catch (err) {
        results.push({ success: false, error: err.message });
      }
    }

    return results;
  }
}

// HTTP Server setup
function createWebhookServer(config = {}) {
  const verifier = new WebhookVerifier(
    config.secret || WEBHOOK_SECRET,
    { tolerance: config.tolerance || TIMESTAMP_TOLERANCE }
  );
  const processor = new EventProcessor();

  // Register default handlers
  processor.registerHandler('payment.completed', async (data) => {
    return { processed: true, paymentId: data.id, amount: data.amount };
  });

  processor.registerHandler('subscription.cancelled', async (data) => {
    return { processed: true, subscriptionId: data.id };
  });

  const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);

    if (req.method !== 'POST' || parsedUrl.pathname !== '/webhooks') {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not found' }));
      return;
    }

    let body = '';
    let bodySize = 0;

    req.on('data', (chunk) => {
      bodySize += chunk.length;
      if (bodySize > MAX_BODY_SIZE) {
        res.writeHead(413, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Payload too large' }));
        req.destroy();
        return;
      }
      body += chunk;
    });

    req.on('end', async () => {
      const signatureHeader = req.headers['x-webhook-signature'];

      if (!signatureHeader) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Missing signature' }));
        return;
      }

      const verification = verifier.verify(signatureHeader, body);

      if (!verification.valid) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: verification.error || 'Invalid signature' }));
        return;
      }

      try {
        const event = JSON.parse(body);
        const results = await processor.processEvent(event);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ received: true, results }));
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON payload' }));
      }
    });
  });

  return { server, verifier, processor };
}

module.exports = { WebhookVerifier, EventProcessor, createWebhookServer };
